// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SeaOrderReassignmentEvent) predicate.SeaOrderReassignmentEvent {
	return predicate.SeaOrderReassignmentEvent(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SeaOrderReassignmentEvent) predicate.SeaOrderReassignmentEvent {
	return predicate.SeaOrderReassignmentEvent(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SeaOrderReassignmentEvent) predicate.SeaOrderReassignmentEvent {
	return predicate.SeaOrderReassignmentEvent(sql.NotPredicates(p))
}
